document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".product-button").forEach(function(t){t.addEventListener("click",function(e){e.preventDefault();e=t.closest(".product-item").querySelector("p");e.hidden=!e.hidden,t.textContent=e.hidden?"Ver detalhes":"Ocultar detalhes",t.setAttribute("aria-expanded",String(!e.hidden))})})});